"""Author the approved six-shot sequence contract; preserve existing frozen outputs."""
from pathlib import Path
import json,hashlib,datetime
P=Path(__file__).resolve().parent;ROOT=P.parents[2];R=ROOT/'research/visual-refinement/sequence-design'
def write(path,text):
 with path.open('x',encoding='utf-8') as out:out.write(text)
def dump(path,value):write(path,json.dumps(value,ensure_ascii=False,indent=2)+'\n')
def line(panel,n,speaker,text,kind='dialogue'):return dict(id=f'{panel}-L{n:02}',speaker=speaker,text=text,kind=kind)
